package com.miniforce.service;
import com.miniforce.dto.DiscussionDtos.*; import com.miniforce.exception.*; import com.miniforce.model.*; import com.miniforce.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class DiscussionService {
 private final DiscussionRepository discussions;private final DiscussionReplyRepository replies; public DiscussionService(DiscussionRepository d,DiscussionReplyRepository r){discussions=d;replies=r;}
 @Transactional(readOnly=true) public List<DiscussionSummary> all(){return discussions.findByDeletedFalseOrderByCreatedAtDesc().stream().map(this::summary).toList();}
 @Transactional(readOnly=true) public DiscussionDetail get(Long id){Discussion d=entity(id);if(d.isDeleted())throw new NotFoundException("Discussion not found");return new DiscussionDetail(d.getId(),d.getTitle(),d.getBody(),d.getAuthor().getId(),d.getAuthor().getUsername(),d.getAuthor().getAvatarKey(),d.getCreatedAt(),replies.findByDiscussionIdOrderByCreatedAtAsc(id).stream().map(x->new ReplyResponse(x.getId(),x.getAuthor().getId(),x.getAuthor().getUsername(),x.getAuthor().getAvatarKey(),x.getBody(),x.getCreatedAt())).toList());}
 @Transactional public DiscussionDetail create(User u,DiscussionRequest r){Discussion d=new Discussion();d.setAuthor(u);d.setTitle(r.title().trim());d.setBody(r.body().trim());discussions.save(d);return get(d.getId());}
 @Transactional public ReplyResponse reply(Long id,User u,ReplyRequest r){Discussion d=entity(id);if(d.isDeleted())throw new NotFoundException("Discussion not found");DiscussionReply x=new DiscussionReply();x.setDiscussion(d);x.setAuthor(u);x.setBody(r.body().trim());replies.save(x);return new ReplyResponse(x.getId(),u.getId(),u.getUsername(),u.getAvatarKey(),x.getBody(),x.getCreatedAt());}
 @Transactional public void moderate(Long id){Discussion d=entity(id);d.setDeleted(true);} private Discussion entity(Long id){return discussions.findById(id).orElseThrow(()->new NotFoundException("Discussion not found"));} private DiscussionSummary summary(Discussion d){return new DiscussionSummary(d.getId(),d.getTitle(),d.getBody(),d.getAuthor().getId(),d.getAuthor().getUsername(),d.getAuthor().getAvatarKey(),d.getCreatedAt(),replies.countByDiscussionId(d.getId()));}
}
